// screens/DetailScreen.js

import React, { useState } from 'react';
import { View, Text, FlatList, Button, StyleSheet } from 'react-native';
import axios from 'axios';

export default function DetailScreen({ route }) {
  const { sensor, apiUrl } = route.params;
  const [history, setHistory] = useState(sensor.history || []);

  const fetchHistory = async () => {
    try {
      // monte a URL completa: exemplo http://localhost:3001/sensors/1
      const url = `${apiUrl}/sensors/${sensor.id}`;
      console.log('Fetching', url);
      const response = await axios.get(url);
      setHistory(response.data.history);
    } catch (error) {
      console.error(error);
    }
  };

  return (
    <View style={styles.container}>
      <Text>Histórico de {sensor.name}</Text>
      <FlatList
        data={history}
        keyExtractor={(_, idx) => idx.toString()}
        renderItem={({ item }) => <Text>{item}</Text>}
      />
      <Button title="Atualizar" onPress={fetchHistory} />
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, padding: 16 }
});
